import { test, expect } from '@playwright/test';

test.describe('Inventory Page Product List Display', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('https://www.saucedemo.com');
  });

  test('should display exactly 6 complete product cards after successful login', async ({ page }) => {
    // Login with standard user credentials
    const usernameInput = page.getByLabel('Username');
    const passwordInput = page.getByLabel('Password');
    const loginButton = page.getByRole('button', { name: 'Log in' });

    await usernameInput.fill('standard_user');
    await passwordInput.fill('secret_sauce');
    await loginButton.click();

    // Wait for inventory page to load
    await page.waitForURL('https://www.saucedemo.com/inventory.');

    // Verify product list container is visible
    const inventoryContainer = page.getByTestId('inventory-container');
    await expect(inventoryContainer).toBeVisible();

    // Verify exactly 6 product cards are displayed
    const productCards = page.getByTestId('inventory-item');
    const cardCount = await productCards.count();
    expect(cardCount).toBe(6);

    // Verify each product card contains a name and price
    for (let i = 0; i < 6; i++) {
      const card = productCards.nth(i);
      const nameElement = card.getByTestId('inventory-item-name');
      const priceElement = card.getByTestId('inventory-item-price');

      await expect(nameElement).toBeVisible();
      await expect(priceElement).toBeVisible();

      const nameText = await nameElement.textContent();
      const priceText = await priceElement.textContent();

      expect(nameText).not.toBeNull();
      expect(nameText.trim()).not.toBe('');
      expect(priceText).toMatch(/^\$\d+\.\d{2}$/);
    }
  });

  test('should handle login failure and display no product cards', async ({ page }) => {
    // Attempt login with invalid credentials
    const usernameInput = page.getByLabel('Username');
    const passwordInput = page.getByLabel('Password');
    const loginButton = page.getByRole('button', { name: 'Log in' });

    await usernameInput.fill('invalid_user');
    await passwordInput.fill('wrongpassword');
    await loginButton.click();

    // Verify error message is displayed
    const errorMessage = page.getByText('Username and password do not match');
    await expect(errorMessage).toBeVisible();

    // Verify inventory page is not loaded
    const inventoryContainer = page.getByTestId('inventory-container');
    await expect(inventoryContainer).not.toBeVisible();

    // Verify no product cards are present
    const productCards = page.getByTestId('inventory-item');
    const cardCount = await productCards.count();
    expect(cardCount).toBe(0);
  });
});
